input.command:
cat > /tmp/an.jq <<'EOF'
def params: ((.parameters//[])|map(.name));
def bodyprops: ((.requestBody.content["application/json"].schema.properties//{})|keys);
paths|to_entries[]|.key as $p|.value|to_entries[]|select(.key|IN("get","post","put","patch","delete"))|
{m:(.key|ascii_upcase),p:$p,id:.value.operationId,sum:.value.summary,dep:(.value.deprecated//false),
 pg:((params+bodyprops)|map(select(.=="start_cursor" or .=="cursor" or .=="page_size"))|join(",")),
 depp:([(.value.parameters//[])[]|select(.deprecated==true)|.name]|join(",")),
 depb:([(.value.requestBody.content["application/json"].schema.properties//{})|to_entries[]|select(.value.deprecated==true)|.key]|join(","))}
EOF
for f in main admin; do echo == $f; jq -r -f /tmp/an.jq $f.spec.json | jq -r '[.m,.p,.sum,.dep,.pg,.depp,.depb]|@tsv'; done

